import { createResource } from 'qortex-resource';

const product = createResource({
  key: ['product', id],
  query: { enabled: true },
  source: {
    fetch: async () => {
      const res = await fetch(`/api/products/${id}`);
      if (!res.ok) throw new Error('Failed to load');
      return res.json();
    },
    save: async (draft, meta) => {
      const res = await fetch(`/api/products/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...draft,
          // optional: tell the API what changed
          _changed: meta.changedFields,
        }),
      });
      if (!res.ok) throw new Error(await res.text());
      return res.json();
    },
  },
});

await product.fetch();
await product.refetch();

function adaptQuery<T>(q: {
  data: T | undefined;
  error: unknown;
  status: string;
  subscribe: (cb: () => void) => () => void;
  refetch: () => Promise<void>;
}) {
  return {
    get data() { return q.data; },
    get error() { return q.error; },
    get status() { return q.status as any; },
    subscribe: q.subscribe,
    refetch: q.refetch,
  };
}

createResource({
