  },
});

import { createStore } from 'qortex-store';
import { createResource } from 'qortex-resource';

const profileStore = createStore({
  name: '',
  email: '',
});

const resource = createResource({
  source: {
    state: {
      get: () => profileStore.get(),
      set: (next) => profileStore.set(next, true),
      subscribe: (cb) => profileStore.subscribe(() => cb()),
    },
    save: async (draft) => {
      await api.profile.save(draft);
      return draft;
    },
  },
});

